INSERT INTO `subject` (`subject_id`, `code`, `title`, `credits`, `department_id`, `program_id`, `semester`, `description`) VALUES
  (1, 'CS101', 'Programming in C', 4, 1, 1, 1, 'Foundations of procedural programming in C. Covers pointers, dynamic memory allocation, arrays, strings, structures, file input/output, recursion, and algorithm problem solving.'),
  (2, 'CS102', 'Digital Logic Design', 3, 1, 1, 1, 'Boolean algebra, logic gates, combinational logic circuits, multiplexers, decoders, flip-flops, sequential circuits, synchronous counters, shift registers, and digital system design.'),
  (3, 'CS201', 'Data Structures', 4, 1, 1, 2, 'Linear and non-linear data structures. Detailed coverage of arrays, linked lists, stacks, queues, binary search trees, AVL trees, heaps, hash tables, graph representations, and asymptotic analysis.'),
  (4, 'CS202', 'Computer Organization and Architecture', 4, 1, 1, 2, 'Instruction set architecture, CPU datapath, pipelining, pipeline hazards, cache memory hierarchies, virtual memory, bus architectures, and peripheral I/O interfacing.'),
  (5, 'CS301', 'Design and Analysis of Algorithms', 4, 1, 1, 3, 'Algorithm design paradigms including divide-and-conquer, greedy algorithms, dynamic programming, backtracking, branch-and-bound. Graph algorithms, shortest paths, minimum spanning trees, and NP-completeness.'),
  (6, 'CS302', 'Database Management Systems', 4, 1, 1, 3, 'Relational data model, relational algebra, SQL querying, functional dependencies, normalization up to 3NF and BCNF, B-tree indexing, transaction ACID properties, concurrency control, and crash recovery.'),
  (7, 'CS303', 'Operating Systems', 4, 1, 1, 4, 'Operating system concepts: processes, threads, CPU scheduling, inter-process communication, semaphores, mutexes, deadlock detection and prevention, memory paging, segmentation, and file systems.'),
  (8, 'CS304', 'Computer Networks', 3, 1, 1, 4, 'OSI and TCP/IP protocol stacks. Physical media, data link layer framing, error correction, IP addressing, routing algorithms, transport layer TCP/UDP mechanisms, and network security protocols.'),
  (9, 'CS401', 'Artificial Intelligence and Machine Learning', 4, 1, 1, 5, 'Supervised and unsupervised learning, linear regression, logistic regression, decision trees, random forests, support vector machines, neural networks, feature engineering, and cross-validation.'),
  (10, 'CS402', 'Web Application Development', 3, 1, 1, 5, 'Modern web development architectures. HTML5, CSS3, JavaScript, React frontend framework, RESTful APIs, Spring Boot microservices, JSON Web Tokens (JWT), and responsive UI design.'),
  (11, 'CS403', 'Compiler Design', 4, 1, 1, 6, 'Lexical analysis, syntax analysis, LL and LR parsing techniques, syntax-directed translation, symbol tables, intermediate code generation, data flow analysis, and code optimization.'),
  (12, 'CS404', 'Cloud Computing and Distributed Systems', 3, 1, 1, 6, 'Distributed computing fundamentals, RPC, cloud virtualization, containerization with Docker, microservices, distributed consensus algorithms, distributed key-value storage, and high availability.'),
  (13, 'CS501', 'Advanced Data Mining', 3, 1, 1, 7, 'Knowledge discovery in large databases. Association rule mining, Apriori, FP-growth, cluster analysis, DBSCAN, outlier detection, text mining, graph mining, and stream analytics.'),
  (14, 'CS502', 'Information and Network Security', 3, 1, 1, 7, 'Cryptography principles, AES, RSA public key cryptography, cryptographic hash functions, digital signatures, key management, firewalls, intrusion detection, SSL/TLS, and penetration testing.'),
  (15, 'EC101', 'Basic Electronics', 3, 2, 4, 1, 'Semiconductor fundamentals, PN junction diodes, Zener diodes, BJT operation, biasing techniques, JFET, MOSFET, operational amplifiers, and rectifier circuits.'),
  (16, 'EC201', 'Signals and Systems', 4, 2, 4, 2, 'Continuous-time and discrete-time signals, linear time-invariant (LTI) systems, convolution, Fourier series, Fourier transform, Laplace transform, and z-transform analysis.'),
  (17, 'EC202', 'Electronic Circuit Analysis', 4, 2, 4, 3, 'Small-signal analysis of BJT and MOSFET amplifiers, frequency response, multistage amplifiers, feedback amplifiers, Barkhausen criterion, sinusoidal oscillators, and tuned amplifiers.'),
  (18, 'EC301', 'Digital Signal Processing', 4, 2, 4, 4, 'Discrete Fourier Transform (DFT), Fast Fourier Transform (FFT) algorithms, design of FIR filters, design of IIR Butterworth and Chebyshev filters, and finite word length effects.'),
  (19, 'EC302', 'Analog and Digital Communication', 4, 2, 4, 5, 'Amplitude modulation, frequency modulation, pulse code modulation (PCM), delta modulation, digital keying techniques (ASK, FSK, PSK, QAM), and channel noise performance.'),
  (20, 'EC401', 'VLSI System Design', 4, 2, 4, 6, 'MOS transistor theory, CMOS inverter characteristics, combinational logic design, dynamic logic, static timing analysis, stick diagrams, layout rules, and Verilog HDL modeling.'),
  (21, 'EC402', 'Embedded Systems and IoT', 3, 2, 4, 6, 'ARM Cortex-M microcontroller architecture, GPIO, timers, ADC, interrupt handling, real-time operating systems (RTOS), IoT sensor interfacing, and wireless protocols (BLE, Zigbee, MQTT).'),
  (22, 'EC501', 'Wireless Communication Networks', 3, 2, 4, 7, 'Cellular concepts, frequency reuse, handoff strategies, wireless channel fading, multipath propagation, CDMA, OFDM, 4G LTE architectures, and 5G New Radio technologies.'),
  (23, 'ME101', 'Engineering Mechanics', 4, 3, 5, 1, 'Statics of particles and rigid bodies, coplanar force systems, trusses, dry friction, center of gravity, moment of inertia, kinematics of particles, Newton laws, and work-energy methods.'),
  (24, 'ME201', 'Thermodynamics', 4, 3, 5, 2, 'Zeroth, First, and Second laws of thermodynamics, pure substances, ideal gas laws, Carnot cycle, entropy, exergy, Rankine cycle, Otto and Diesel cycles, and psychrometric charts.'),
  (25, 'ME202', 'Fluid Mechanics', 4, 3, 5, 3, 'Fluid statics, buoyancy, fluid kinematics, stream functions, continuity equation, Navier-Stokes equations, Bernoulli equation, laminar and turbulent pipe flow, and boundary layer theory.'),
  (26, 'ME301', 'Heat and Mass Transfer', 4, 3, 5, 4, 'Modes of heat transfer: steady and unsteady conduction, lumped capacitance method, forced and free convection, radiation laws, Stefan-Boltzmann law, heat exchanger design, and Fick law.'),
  (27, 'ME302', 'Machine Design', 4, 3, 5, 5, 'Design of machine elements against static and fatigue failure. Design of shafts, keys, couplings, bolted and welded joints, helical springs, spur gears, and rolling element bearings.'),
  (28, 'ME401', 'Manufacturing Technology', 3, 3, 5, 6, 'Metal casting processes, gating design, bulk deformation, metal forming, sheet metal working, arc welding, resistance welding, CNC machining, metrology, and additive manufacturing.'),
  (29, 'CE101', 'Solid Mechanics', 4, 4, 6, 1, 'Stress and strain relationships, Hooke law, axial deformation, torsion of circular shafts, shear force and bending moment diagrams, flexural stresses, and Mohr stress circles.'),
  (30, 'CE201', 'Structural Analysis', 4, 4, 6, 2, 'Analysis of determinate and indeterminate structures, slope-deflection equations, moment distribution method, strain energy methods, influence lines for continuous beams, and truss analysis.'),
  (31, 'CE202', 'Surveying and Geomatics', 3, 4, 6, 2, 'Principles of surveying, chain and compass survey, levelling, theodolite traverse, contouring, curves, Total Station operations, Global Positioning System (GPS), and GIS fundamentals.'),
  (32, 'CE301', 'Geotechnical Engineering', 4, 4, 6, 3, 'Soil formation, phase relationships, soil classification, permeability, seepage, effective stress principle, consolidation settlement, shear strength criteria, and lateral earth pressures.'),
  (33, 'CE302', 'Reinforced Concrete Design', 4, 4, 6, 4, 'Limit state design philosophy, design of singly and doubly reinforced beams, flanged beams, one-way and two-way slabs, short and slender columns, and isolated footings per IS 456.'),
  (34, 'MA101', 'Calculus and Linear Algebra', 4, 5, 7, 1, 'Single variable calculus, Mean Value Theorems, Taylor series, vector spaces, linear transformations, matrix operations, rank, systems of linear equations, eigenvalues, and eigenvectors.'),
  (35, 'MA201', 'Multivariable Calculus and Differential Equations', 4, 5, 7, 2, 'Partial derivatives, gradient, directional derivatives, multiple integrals, line and surface integrals, Green, Stokes, and Gauss divergence theorems, and ordinary differential equations.'),
  (36, 'MA301', 'Probability and Statistics', 4, 5, 7, 3, 'Probability axioms, conditional probability, Bayes theorem, discrete and continuous random variables, joint distributions, Central Limit Theorem, hypothesis testing, and regression analysis.'),
  (37, 'MA401', 'Numerical Methods and Optimization', 3, 5, 7, 4, 'Numerical solutions of algebraic equations, Newton-Raphson, polynomial interpolation, numerical differentiation and integration, Runge-Kutta methods, and linear programming simplex method.'),
  (38, 'PH101', 'Engineering Physics', 3, 6, 8, 1, 'Wave optics, interference in thin films, diffraction gratings, polarization of light, lasers and fiber optics, electromagnetism, Maxwell equations, and electromagnetic wave propagation.'),
  (39, 'PH201', 'Quantum Mechanics and Modern Physics', 4, 6, 8, 2, 'Inadequacy of classical mechanics, wave-particle duality, de Broglie hypothesis, Heisenberg uncertainty principle, Schrodinger wave equation, particle in a box, and quantum tunneling.'),
  (40, 'PH301', 'Solid State Physics', 3, 6, 8, 3, 'Crystalline states, Bravais lattices, Miller indices, X-ray diffraction, Bragg law, free electron theory of metals, band theory of solids, semiconductors, superconductivity, and magnetism.');
